package GUI;
import Program.model.User; import Program.service.AuthService; import javafx.geometry.*; import javafx.scene.control.*; import javafx.scene.layout.*;
/** Programmatic equivalent of Login.fxml; the project intentionally remains Java-only. */
public class LoginUI extends StackPane {public LoginUI(MainUI app,AuthService auth){getStyleClass().add("auth-root");setAlignment(Pos.CENTER);VBox card=new VBox(15);card.setAlignment(Pos.CENTER_LEFT);card.setMaxWidth(400);card.setPrefWidth(400);card.setPadding(new Insets(36));card.getStyleClass().add("auth-card");HBox brand=new HBox(10,UIFactory.logoBadge(),new Label("EXPENSE INTELLIGENCE"));brand.setAlignment(Pos.CENTER_LEFT);((Label)brand.getChildren().get(1)).getStyleClass().add("brand");TextField username=UIFactory.field("Username");PasswordField password=new PasswordField();password.setPromptText("Password");Button login=UIFactory.button("Login","primary-button");login.setMaxWidth(Double.MAX_VALUE);Hyperlink register=new Hyperlink("New here? Create an account");login.setOnAction(e->{try{User user=auth.login(username.getText(),password.getText());app.showApp(user);}catch(Exception error){UIFactory.error(error.getMessage());}});password.setOnAction(e->login.fire());register.setOnAction(e->app.showRegister());card.getChildren().addAll(brand,UIFactory.title("Welcome back"),UIFactory.muted("Sign in to your smart finance workspace"),new Label("USERNAME"),username,new Label("PASSWORD"),password,login,register);getChildren().add(card);}}
